DECLARE
  v_politica redaction_policies.policy_name%TYPE;
BEGIN
  BEGIN
    SELECT policy_name INTO v_politica FROM redaction_policies
     WHERE object_owner = '{esquema!l}' AND object_name = '{tabla!l}';
    DBMS_REDACT.ALTER_POLICY(object_schema => '{esquema!l}', object_name => '{tabla!l}',
      policy_name => v_politica, action => DBMS_REDACT.ADD_COLUMN,
      column_name => '{columna!l}', function_type => DBMS_REDACT.FULL);
  EXCEPTION WHEN NO_DATA_FOUND THEN
    DBMS_REDACT.ADD_POLICY(object_schema => '{esquema!l}', object_name => '{tabla!l}',
      policy_name => 'POL_REDACT_{tabla!l}', column_name => '{columna!l}',
      function_type => DBMS_REDACT.FULL, expression => '1=1');
  END;
END;
/

-- Ejecutar en RMAN (rman target /). El respaldo {pieza!l} se reemplaza por uno cifrado:
-- CONFIGURE ENCRYPTION FOR DATABASE ON;
-- CONFIGURE ENCRYPTION ALGORITHM 'AES256';
-- BACKUP DATABASE PLUS ARCHIVELOG;
-- DELETE OBSOLETE;

CREATE AUDIT POLICY POL_ISO_{esquema!b}_{tabla!b}
  ACTIONS SELECT ON {esquema}.{tabla},
          INSERT ON {esquema}.{tabla},
          UPDATE ON {esquema}.{tabla},
          DELETE ON {esquema}.{tabla};
AUDIT POLICY POL_ISO_{esquema!b}_{tabla!b};

